use serde_json::{json,Value};
use tron_apis::{JsonRpcBackend,JsonRpcError,TronJsonRpcConfig,TronJsonRpcMethods,TRON_JSON_RPC_METHODS};
struct Backend;
impl JsonRpcBackend for Backend{fn execute(&self,m:&str,_:&Value)->Result<Value,JsonRpcError>{Ok(json!({"method":m}))}}
#[test] fn inventory_is_exact_and_unique(){assert_eq!(TRON_JSON_RPC_METHODS.len(),52);let mut v=TRON_JSON_RPC_METHODS.to_vec();v.sort_unstable();v.dedup();assert_eq!(v.len(),52);assert!(!TRON_JSON_RPC_METHODS.contains(&"eth_feeHistory"));}
#[test] fn constants_sha3_chain_id_and_deliberate_results(){let mut c=TronJsonRpcConfig::default();c.genesis_hash[28..].copy_from_slice(&0x1234u32.to_be_bytes());c.peer_count=2;let rpc=TronJsonRpcMethods::new(c,Backend);assert_eq!(rpc.execute("eth_chainId",&json!([])).unwrap(),"0x00001234");assert_eq!(rpc.execute("net_version",&json!([])).unwrap(),"0x00001234");assert_eq!(rpc.execute("eth_blockNumber",&json!([])).unwrap(),json!({"method":"eth_blockNumber"}));assert_eq!(rpc.execute("net_peerCount",&json!([])).unwrap(),"0x2");assert_eq!(rpc.execute("web3_sha3",&json!(["0x"])).unwrap(),"0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470");assert_eq!(rpc.execute("eth_getUncleByBlockHashAndIndex",&json!([])).unwrap(),Value::Null);assert_eq!(rpc.execute("eth_getUncleCountByBlockHash",&json!([])).unwrap(),"0x0");}
#[test] fn unsupported_and_accidental_ethereum_methods_are_not_exposed(){let rpc=TronJsonRpcMethods::new(TronJsonRpcConfig::default(),Backend);for name in ["eth_sendRawTransaction","eth_sign","parity_nextNonce","eth_submitHashrate","eth_feeHistory"]{assert_eq!(rpc.execute(name,&json!([])).unwrap_err().code,-32601);}}
